//! Consumer of synthetic fixtures generated by the actual schema-27 revision.
//! Keep database inspection inside Storage's test boundary, without exposing
//! a connection or broadening the production API for cross-version tests.
use crate::bootstrap::Bootstrap;
use rusqlite::{Connection, OpenFlags};
use std::path::{Path, PathBuf};
use uuid::Uuid;

#[derive(serde::Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
struct HistoricalFixture {
    schema_version: u32,
    source_revision: String,
    root: PathBuf,
    config: PathBuf,
    legacy: PathBuf,
    target: PathBuf,
    meeting: String,
    deletion: String,
    full_deletion: Option<String>,
    model_operation: String,
    model_file: PathBuf,
}

fn historical_records(root: &Path) -> String {
    let db = Connection::open_with_flags(
        root.join("meetings.sqlite3"),
        OpenFlags::SQLITE_OPEN_READ_ONLY | OpenFlags::SQLITE_OPEN_NOFOLLOW,
    )
    .unwrap();
    assert_eq!(crate::storage::verify_migration_history(&db).unwrap(), 27);
    historical_records_database(&db)
}

fn historical_records_database(db: &Connection) -> String {
    db.query_row("SELECT json_array((SELECT json_group_array(json_array(id,meeting_id,kind,state,target_manifest_json,target_hash,consent_at,progress_json,error_code,created_at,updated_at)) FROM (SELECT * FROM maintenance_operations ORDER BY id)),(SELECT json_group_array(json_array(operation_id,relative_path,kind,size_bytes,content_hash,identity_json,identity_hash)) FROM (SELECT * FROM maintenance_paths ORDER BY operation_id,relative_path)))",[],|r|r.get(0)).unwrap()
}

#[test]
#[ignore = "requires MON_HISTORY_V27_FIXTURE_INDEX generated by actual schema-27 revision; synthetic owned fixtures only"]
fn history_v27_actual_selected_move_cold_start_migrates_and_retains_all_native_history() {
    let path = std::env::var("MON_HISTORY_V27_FIXTURE_INDEX").unwrap();
    let bytes = std::fs::read(path).unwrap();
    assert!(bytes.len() < 65536);
    let fixtures: Vec<HistoricalFixture> = serde_json::from_slice(&bytes).unwrap();
    assert_eq!(fixtures.len(), 2);
    for fixture in fixtures {
        let root = fixture.root.canonicalize().unwrap();
        assert_eq!(fixture.schema_version, 27);
        assert_eq!(
            fixture.source_revision,
            "f930f4f0c2dd1c2502c8515f9e1d96624e7050c7"
        );
        assert_eq!(
            std::fs::read(root.join(".mon-v27-cross-version-fixture")).unwrap(),
            fixture.source_revision.as_bytes()
        );
        assert_eq!(fixture.config, root.join("config"));
        assert_eq!(fixture.legacy, root.join("app-data"));
        assert_eq!(fixture.target, root.join("target"));
        assert!(fixture.model_file.starts_with(&root));
        assert!(Uuid::parse_str(&fixture.meeting).is_ok());
        assert!(Uuid::parse_str(&fixture.deletion).is_ok());
        assert!(Uuid::parse_str(&fixture.model_operation).is_ok());
        if let Some(id) = &fixture.full_deletion {
            assert!(Uuid::parse_str(id).is_ok());
        }
        let before = historical_records(&fixture.target);
        // A fresh Bootstrap places the initial meeting root under app-data/data;
        // legacy is the app-data input, not the selected meeting root.
        let old_database = fixture.legacy.join("data/meetings.sqlite3");
        let old_source = std::fs::read(&old_database).unwrap();
        let bootstrap = Bootstrap::open(&fixture.config, &fixture.legacy).unwrap();
        let storage = bootstrap.open_storage().unwrap();
        assert_eq!(storage.root(), fixture.target);
        assert!(!storage.data_write_blocked());
        assert_eq!(
            historical_records_database(&storage.connection.lock().unwrap()),
            before
        );
        assert!(!fixture.model_file.exists());
        if fixture.full_deletion.is_some() {
            assert!(storage.get_meeting(&fixture.meeting).unwrap().is_none());
        }
        {
            let db = storage.connection.lock().unwrap();
            assert_eq!(crate::storage::verify_migration_history(&db).unwrap(), 28);
            if fixture.full_deletion.is_none() {
                assert!(
                    crate::storage::deletion::audio::require_source(&db, &fixture.meeting)
                        .unwrap_err()
                        .contains("音声は削除済み")
                );
            }
        }
        storage
            .create_meeting("SAFE CURRENT WRITE AFTER V27 MOVE UPGRADE")
            .unwrap();
        drop(storage);
        drop(bootstrap);
        let bootstrap = Bootstrap::open(&fixture.config, &fixture.legacy).unwrap();
        let storage = bootstrap.open_storage().unwrap();
        assert!(!storage.data_write_blocked());
        assert_eq!(
            historical_records_database(&storage.connection.lock().unwrap()),
            before
        );
        assert_eq!(std::fs::read(&old_database).unwrap(), old_source);
        assert!(!fixture.model_file.exists());
    }
}
